-- 294: compute_maxbld_scenarios (Layer 3, MB-31) — the increment-1 settings the catalogue rows read through lv(), plus the population list.

-- Mirrors scripts/seeds/logic_variables.json entry for entry (the seed file is the test truth; this migration puts the same
-- rows in the table the admin screen and the runner read). S-1 / S-2 are M-404 (69a:541), G-1 is the footprint shape factor
-- (queue :49), the two ring settings are CARD-fs-sb2a (L31-16 bounds 2..4 and 1..4). No value is carried over from the old engine.
-- WRITTEN, NOT APPLIED (DB window; one writer; MB-35 confirms the order). Idempotent: ON CONFLICT (variable_key) DO NOTHING
-- preserves any operator-set value.
--
-- SPEC LINK: docs/specs/01-pipeline/69a_mcbylaw_register.md M-404
-- SPEC LINK: docs/specs/01-pipeline/124_step_standard_policy.md (Rule 3; R-CV; R-DE (v))

-- UP
INSERT INTO logic_variables (variable_key, variable_value, variable_value_json, description) VALUES
  ('s1_ceiling_min_m', 2.3, NULL, 'S-1 (M-404, 69a:541; card CARD-aj3-four item 1): minimum finished ceiling height in living, dining and kitchen space, over at least 75 % of the area. CITE: Ontario Building Code 2024, Part 9, Table 9.5.3.1. Floor-to-floor f = s1_ceiling_min_m + s1_floor_assembly_m. Pinned: changes only by a ruling. CONSUMED by the catalogue row storeys_max (scripts/analysis/bylaw evaluator, lv()).'),
  ('s1_floor_assembly_m', 0.212, NULL, 'S-1 (M-404): one floor assembly = joist 184 mm (Table 9.23.4.2.-A) + subfloor 15.5 mm (Table 9.23.15.5.-A) + ceiling board 12.7 mm (Table 9.29.5.3) = 212.2 mm; finished floor and furring are 0 and disclosed as not cited; the 184 mm joist is a disclosed design choice. CITE: OBC 2024 Part 9 tables named. Roof allowance a = s1_floor_assembly_m + s1_parapet_m. Pinned. CONSUMED by storeys_max.'),
  ('s1_parapet_m', 0.3, NULL, 'S-1 (M-404): roof allowance beyond one floor assembly. CITE: 10.20.40.10(5); that regulation governs RD main wall height only, so its use for building height is a disclosed extension. Pinned. CONSUMED by storeys_max.'),
  ('s2_first_floor_above_grade_m', 0, NULL, 'S-2 (M-405, 69a:542; card wave0 section B): first floor height above established grade, taken as 0 and disclosed as an assumption; subtracted from the height before S-1 converts it. Changes only by a ruling. Pinned. CONSUMED by storeys_max.'),
  ('footprint_shape_factor', 1, NULL, 'LC-69 (131:119), M-392, M-418: the footprint is a box, disclosed ''box shape assumed; entrances and projections not modelled''. This factor is 1.0 while the switchboard reading shape_calibration is off; it is read only when that switch is on AND a fitted value with provenance (n cases, date, audit file) exists (R3-10 fails closed). Bounds are pinned 1..1 because M-392 was approved without the proposed [0.5, 1.0]; a later ruling sets them. CONSUMED by the catalogue row footprint_max_m2.'),
  ('compute_maxbld_scenarios_population_parcel_ids', 0, '["6640","30065","30554","33830","119522","120669","122034","153191","159079","169742","170105","173273","205238","216666","258388","274216","283723","304365","313999","403569","410720","427312","428050","442123","461807"]'::jsonb, 'Increment-1 population of compute_maxbld_scenarios (R-BT: the population is a query; this list narrows it): the 25 golden parcel ids of MB-64 (data/golden-parcel-map.json). An empty list means no parcel is computed. Widened by a setting change in the later increments (Q:85-94), never by code. List-typed: stored in variable_value_json (seed type list, Q-J), as DECIMAL STRINGS because the step library validates a list as distinct members of a closed list_of of strings (scripts/lib/step/config.js); the step converts them to integers (populationIds) before it binds them. Widening the population changes this seed AND the descriptor list_of together (operator answer CARD-mb31-inc1-blockers, blocker 2 option 2). CONSUMED by the step''s population query. CONSUMED by the step''s population query.'),
  ('fya_placeholder_ring_depth', 2, NULL, 'CARD-fs-sb2a (FS-SB2a, operator 2026-10-31, amends FS-SB2 / card CARD-front-setback-placeholder; Spec 69a M-245, M-256; evidence ~/Buildo-scratch/mcbylaws/research/Q4-neighbour-ring-vs-FS-SB2.md, 264 lots: FS-SB2 MAE 1.28 m, ring hybrid 1.10 m): where neighbours exist but their front setbacks cannot be measured, the street term of the placeholder is the mean of the measurable footprint estimates + fya_porch_allowance_m of the ring lots beyond the abutters along the frontage street, else the same-street median + the allowance; the term is averaged with the lot''s own front setback + the allowance; always needs survey. This variable: ring depth, the number of lots along the frontage street in each walked direction counting the abutter as lot 1 (2 means the lot beyond each abutter). A fitted value, not law: bounded, fit_basis the held-out audit of Q4 (depth 2 MAE 1.10 m, depth 3 1.13 m), re-fit by a split-sample check now and a true re-fit when newly measured lots exist (L31-18). CONSUMED by the step compute_maxbld_scenarios declared read 6 (ring lots); the catalogue row does not read it. Calibration provisional (CARD-l31-15-16-18).'),
  ('fya_placeholder_ring_min_n', 1, NULL, 'CARD-fs-sb2a (FS-SB2a, operator 2026-10-31, amends FS-SB2 / card CARD-front-setback-placeholder; Spec 69a M-245, M-256; evidence ~/Buildo-scratch/mcbylaws/research/Q4-neighbour-ring-vs-FS-SB2.md, 264 lots: FS-SB2 MAE 1.28 m, ring hybrid 1.10 m): where neighbours exist but their front setbacks cannot be measured, the street term of the placeholder is the mean of the measurable footprint estimates + fya_porch_allowance_m of the ring lots beyond the abutters along the frontage street, else the same-street median + the allowance; the term is averaged with the lot''s own front setback + the allowance; always needs survey. This variable: minimum number of measurable ring lots for the ring term to count; below it the same-street median is the street term. A fitted value, not law (min 1: MAE 1.10 m; min 2: 1.16 m). CONSUMED by the catalogue row front_setback_used_m (lv). Calibration provisional (CARD-l31-15-16-18).')
ON CONFLICT (variable_key) DO NOTHING;

